package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"net"
	"syscall"

	appstats "github.com/xtls/xray-core/app/stats"
	"github.com/xtls/xray-core/common"
	buf "github.com/xtls/xray-core/common/buf"
	"github.com/xtls/xray-core/transport/internet/stat"
)

var injected = errors.New("injected partial write")

type prefixFailureConn struct {
	net.Conn
	failed bool
}

func (c *prefixFailureConn) SyscallConn() (syscall.RawConn, error) {
	return c.Conn.(syscall.Conn).SyscallConn()
}
func (c *prefixFailureConn) Write(p []byte) (int, error) {
	if !c.failed {
		c.failed = true
		n := 3
		if n > len(p) { n = len(p) }
		written, err := c.Conn.Write(p[:n])
		if err != nil { return written, err }
		return written, injected
	}
	return c.Conn.Write(p)
}

func managed(s string) *buf.Buffer {
	b := buf.New()
	common.Must2(b.WriteString(s))
	return b
}

func accept(listener net.Listener, n int) ([]byte, error) {
	conn, err := listener.Accept()
	if err != nil { return nil, err }
	defer conn.Close()
	got := make([]byte, n)
	_, err = io.ReadFull(conn, got)
	return got, err
}

func main() {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	common.Must(err)
	payload := []byte("alpha|beta|gamma|")
	peer := make(chan struct { b []byte; err error }, 1)
	go func() { b, e := accept(listener, len(payload)); peer <- struct { b []byte; err error }{b, e} }()
	client, err := net.Dial("tcp", listener.Addr().String())
	common.Must(err)
	var counter appstats.Counter
	writer := buf.NewWriter(&stat.CounterConnection{Connection: client, WriteCounter: &counter})
	input := buf.MultiBuffer{managed("alpha|"), managed("beta|"), managed("gamma|")}
	inputOwned := append([]*buf.Buffer(nil), input...)
	common.Must(writer.WriteMultiBuffer(input))
	for _, b := range inputOwned { if b.Bytes() != nil { panic("positive managed buffer not released") } }
	got := <-peer
	if got.err != nil { panic(got.err) }
	if !bytes.Equal(got.b, payload) { panic(fmt.Sprintf("positive bytes %q want %q", got.b, payload)) }
	if counter.Value() != int64(len(payload)) { panic(fmt.Sprintf("positive counter %d want %d", counter.Value(), len(payload))) }
	common.Must(client.Close())
	common.Must(listener.Close())

	listener, err = net.Listen("tcp", "127.0.0.1:0")
	common.Must(err)
	peer = make(chan struct { b []byte; err error }, 1)
	go func() { b, e := accept(listener, len("preNEXT")); peer <- struct { b []byte; err error }{b, e} }()
	client, err = net.Dial("tcp", listener.Addr().String())
	common.Must(err)
	wrapped := &prefixFailureConn{Conn: client}
	var partialCounter appstats.Counter
	writer = buf.NewWriter(&stat.CounterConnection{Connection: wrapped, WriteCounter: &partialCounter})
	first := buf.MultiBuffer{managed("prefix"), managed("discard")}
	firstOwned := append([]*buf.Buffer(nil), first...)
	err = writer.WriteMultiBuffer(first)
	partialErr := err
	if !errors.Is(err, injected) { panic(fmt.Sprintf("partial error %v, want injected", err)) }
	for _, b := range firstOwned { if b.Bytes() != nil { panic("error-path managed buffer not released") } }
	if partialCounter.Value() != 3 { panic(fmt.Sprintf("partial counter %d want 3", partialCounter.Value())) }
	nextHead, nextTail := managed("NE"), managed("XT")
	nextOwned := []*buf.Buffer{nextHead, nextTail}
	common.Must(writer.WriteMultiBuffer(buf.MultiBuffer{nextHead, nextTail}))
	for _, b := range nextOwned { if b.Bytes() != nil { panic("post-error managed buffer not released") } }
	got = <-peer
	if got.err != nil { panic(got.err) }
	if !bytes.Equal(got.b, []byte("preNEXT")) { panic(fmt.Sprintf("post-error bytes %q want %q", got.b, "preNEXT")) }
	if partialCounter.Value() != int64(len("preNEXT")) { panic(fmt.Sprintf("post-error counter %d want %d", partialCounter.Value(), len("preNEXT"))) }
	common.Must(client.Close())
	common.Must(listener.Close())
	listener, err = net.Listen("tcp", "127.0.0.1:0")
	common.Must(err)
	closedConn, err := net.Dial("tcp", listener.Addr().String())
	common.Must(err)
	common.Must(closedConn.Close())
	var emptyCounter appstats.Counter
	emptyWriter := buf.NewWriter(&stat.CounterConnection{Connection: closedConn, WriteCounter: &emptyCounter})
	empty := managed("")
	emptyOriginal := empty
	err = emptyWriter.WriteMultiBuffer(buf.MultiBuffer{nil, empty})
	if err != nil { panic(fmt.Sprintf("closed-TCP empty input returned %v", err)) }
	if emptyCounter.Value() != 0 { panic(fmt.Sprintf("empty counter %d want 0", emptyCounter.Value())) }
	if emptyOriginal.Bytes() != nil { panic("managed empty buffer not released") }
	common.Must(listener.Close())
	fmt.Printf("positive_bytes=%q positive_counter=%d ownership_released=true partial_error=%q partial_counter=3 post_error_bytes=%q final_counter=%d closed_tcp_empty=nil+managed-empty error=<nil> counter=%d empty_released=true\n", []byte(payload), int64(len(payload)), partialErr, got.b, partialCounter.Value(), emptyCounter.Value())
}
